/** Helper: reviews tagged for a service slug (falls back to featured) */
function getTestimonialsFor($slug, $limit = 3) {
    global $testimonials;
    $out = array_values(array_filter($testimonials, fn($t) => $t['service'] === $slug));
    if (count($out) < $limit) {
        foreach ($testimonials as $t) {
            if ($t['featured'] && !in_array($t, $out, true)) { $out[] = $t; }
            if (count($out) >= $limit) { break; }
        }
    }
    return array_slice($out, 0, $limit);
}
